  (* [comment removed for export] *)
  Section JRD.
    Variables (mm : word -> option byte) (fjunk : list byte).
    Hypothesis MIm : mem_inv bsegs mm.
    Hypothesis SRCm : bytes_at bsegs mm (bv_unsigned a1) src.
    Hypothesis DSTm : rw_cells bsegs mm (bv_unsigned a0) [CB (Z.to_nat (bv_unsigned a2)) junk].
    Hypothesis FR1 : FRAME mm.
    Hypothesis FR : rw_cells bsegs mm (bv_unsigned sp + -2160) [CB 2080 fjunk].
    Hypothesis STm : stk bsegs mm lo (bv_unsigned sp + -2160).
    Hypothesis MU : munch W m mm.
    Hypothesis WM : wmono bsegs m mm.
    Hypothesis C6 : rw_cells bsegs mm 1185280 [C8 (Z_to_bv 64 1120948)].
    Hypothesis G1 : rw_cells bsegs mm 1177224 [C8 (Z_to_bv 64 1234872)].
    Hypothesis C1 : rw_cells bsegs mm 1234872 [C8 (Z_to_bv 64 2147450880)].
    Hypothesis G2 : rw_cells bsegs mm 1177232 [C8 (Z_to_bv 64 1238184)].
    Hypothesis G3 : rw_cells bsegs mm 1177240 [C8 (Z_to_bv 64 1238192)].
    Hypothesis G4 : rw_cells bsegs mm 1177248 [C8 (Z_to_bv 64 1238176)].
    Hypothesis C4 : rw_cells bsegs mm 1238176 [C8 (Z_to_bv 64 (2 ^ 47 - 1)); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)].

